                    // Method ids of the ActionService interface (tizen_actions.tidl)
                    private enum ActionMethodId : int
                    {
                        __Result = 0,
                        __Callback = 1,
                        SetProviderEnabled = 15,
                        IsProviderEnabled = 16,
                    }

                    /// <summary>
                    /// Gets whether the proxy is connected to the Action Framework service.
                    /// </summary>
                    public bool IsConnected
                    {
                        get { return _online; }
                    }

                    /// <summary>
                    /// Connects to the Action Framework service. This method blocks until connected.
                    /// </summary>
                    /// <exception cref="InvalidIDException">
                    /// Thrown when the service is not available.
                    /// </exception>
                    /// <exception cref="InvalidIOException">
                    /// Thrown when internal I/O error happen.
                    /// </exception>
                    /// <exception cref="PermissionDeniedException">
                    /// Thrown when the access is denied.
                    /// </exception>
                    public void Connect()
                    {
                        ConnectSync(_actionServiceAppId, _actionServicePortName);
                    }

                    /// <summary>
                    /// Disconnects from the Action Framework service.
                    /// </summary>
                    /// <exception cref="System.InvalidOperationException">
                    /// Thrown when an internal IO error occurrs.
                    /// </exception>
                    public void Disconnect()
                    {
                        // Serialize with Invoke(): it uses the port until its reply arrives.
                        lock (_lock)
                        {
                            Port?.Disconnect();
                            _online = false;
                        }
                    }

                    /// <summary>
                    /// Enables or disables this app as a provider of the action.
                    /// </summary>
                    /// <param name="action_name">The name of the action</param>
                    /// <param name="enabled">true to enable, false to disable</param>
                    /// <returns>1 on success, -1 if this app does not provide the action, -2 on failure</returns>
                    /// <exception cref="NotConnectedSocketException">
                    /// Thrown when the proxy is not connected.
                    /// </exception>
                    /// <exception cref="InvalidIOException">
                    /// Thrown when internal I/O error happen.
                    /// </exception>
                    public int SetProviderEnabled(string action_name, bool enabled)
                    {
                        UnitMap map = new UnitMap();
                        map.Write(1355467489 /*[METHOD]*/, (int)ActionMethodId.SetProviderEnabled);
                        map.Write(1583556340 /*action_name*/, action_name);
                        map.Write(-1609594047 /*enabled*/, enabled);
                        return Invoke(map);
                    }

                    /// <summary>
                    /// Checks whether this app is enabled as a provider of the action.
                    /// </summary>
                    /// <param name="action_name">The name of the action</param>
                    /// <returns>1 if enabled, 0 if disabled, -1 if this app does not provide the action, -2 on failure</returns>
                    /// <exception cref="NotConnectedSocketException">
                    /// Thrown when the proxy is not connected.
                    /// </exception>
                    /// <exception cref="InvalidIOException">
                    /// Thrown when internal I/O error happen.
                    /// </exception>
                    public int IsProviderEnabled(string action_name)
                    {
                        UnitMap map = new UnitMap();
                        map.Write(1355467489 /*[METHOD]*/, (int)ActionMethodId.IsProviderEnabled);
                        map.Write(1583556340 /*action_name*/, action_name);
