                    private int Invoke(UnitMap map)
                    {
                        if (!_online)
                            throw new NotConnectedSocketException();

                        using (Parcel p = new Parcel())
                        {
                            ParcelHeader header = p.GetHeader();
                            header.SetTag(_tidlVersion + ":2:15");
                            map.Serialize(p);

                            lock (_lock)
                            {
                                p.Send(Port);

                                UnitMap mapReceived;
                                Parcel ret_parcel;
                                ConsumeCommand(out mapReceived, out ret_parcel, Port, header);
                                if (mapReceived == null)
                                {
