                                using (ret_parcel)
                                {
                                    if (mapReceived.ContainsName(-1571313492 /*[REMOTE_EXCEPTION]*/))
                                    {
                                        mapReceived.Read(-1571313492 /*[REMOTE_EXCEPTION]*/, out RemoteException exception);
                                        throw exception;
                                    }

                                    if (!mapReceived.ContainsName(1497479973 /*[RESULT]*/))
                                    {
