                                p = new Parcel(port);
                            }
                            catch (InvalidIOException)
                            {
                                unitMap = null;
                                parcelReceived = null;
                                return;
                            }

                            ParcelHeader headerReceived = p.GetHeader();
                            if (!string.IsNullOrEmpty(headerReceived.GetTag()))
                            {
