                                    result_map.Write(-1571313492 /*[REMOTE_EXCEPTION]*/, ex);
                                } else {
                                    try
                                    {
                                        var retVal = b.AddEvent(param1, out TizenEntityCalendarEvent param2);
                                        result_map.Write(1497479973 /*[RESULT]*/, retVal);
                                        result_map.Write_optional_TizenEntityCalendarEvent(-934426595 /*result*/, param2);
                                    } catch (RemoteException ex)
                                    {
                                        result_map.Write(-1571313492 /*[REMOTE_EXCEPTION]*/, ex);
